INSERT INTO public.annotations (term, content)
VALUES
  ('Серендипность', 'Способность находить ценные и неожиданные решения, идеи или открытия случайно, не ставя их целью поиска. Термин ввёл английский писатель Хорас Уолпол в 1754 году по мотивам персидской сказки о трёх принцах из Серендипа.'),
  ('Апофения', 'Переживание и стремление видеть закономерные связи или скрытый смысл там, где объективно присутствуют лишь случайные совпадения. Понятие сформулировал немецкий психиатр Клаус Конрад в 1958 году.'),
  ('Парейдолия', 'Разновидность зрительной или слуховой иллюзии, при которой мозг распознаёт знакомые образы (чаще всего человеческие лица) в случайных формах — облаках, узорах камня или тенях.'),
  ('Атараксия', 'В античной философии (у стоиков, эпикурейцев и скептиков) — высшее душевное спокойствие, невозмутимость и ясность ума, свободные от страха, тревог и разрушительных страстей.'),
  ('Эвдемония', 'Философская категория древнегреческой этики (особенно у Аристотеля), обозначающая высшее человеческое благо и процветание, достигаемое через добродетельную жизнь и реализацию разума.'),
  ('Катарсис', 'Нравственное и эмоциональное очищение через сильное эстетическое переживание — например, сострадание и потрясение при восприятии трагедии или великого произведения искусства.'),
  ('Эмерджентность', 'Появление у сложной системы новых свойств и качеств, которыми не обладает ни один из составляющих её элементов по отдельности (например, сознание как результат взаимодействия нейронов).'),
  ('Петрикор', 'Характерный землистый аромат, возникающий после дождя на сухой почве. Вызывается растительными маслами и веществом геосмин, выделяемым почвенными микроорганизмами.'),
  ('Фосфен', 'Зрительное ощущение цветных пятен, колец или искр, возникающее без воздействия света на глаз — например, при лёгком нажатии на веки или в темноте.'),
  ('Синестезия', 'Нейрологический феномен перекрёстного восприятия, при котором раздражение одного органа чувств автоматически вызывает ощущения другого (например, «цветной слух» или ощущение вкуса у слов).'),
  ('Эйдетика', 'Особый вид памяти и образного мышления, позволяющий удерживать в сознании предельно детальные зрительные, слуховые или иные чувственные образы спустя длительное время после исчезновения объекта.'),
  ('Эпистемология', 'Раздел философии, изучающий природу человеческого познания, структуру знания, критерии истины, границы достоверности и способы обоснования научных теорий.'),
  ('Онтология', 'Фундаментальный раздел философии, исследующий бытие как таковое: что существует, каковы основные категории реальности, пространства, времени и причинности.'),
  ('Герменевтика', 'Искусство и методология истолкования текстов, исторических источников и произведений культуры с учётом авторского замысла и культурно-исторического контекста.'),
  ('Феноменология', 'Философское направление XX века (Эдмунд Гуссерль), изучающее структуры сознания и то, как явления («феномены») непосредственно даны в человеческом опыте.'),
  ('Гносеология', 'Теория познания — философская дисциплина, анализирующая взаимоотношение субъекта и объекта в познавательном процессе, роль чувств, разума и практики.'),
  ('Аксиология', 'Философское учение о ценностях, их происхождении, природе, иерархии и месте в структуре человеческого бытия и культуры.'),
  ('Телеология', 'Учение о целесообразности и направленности процессов в природе, истории или деятельности человека, объясняющее явления через их конечную цель или назначение.'),
  ('Диалектика', 'Философский метод рассуждения и познания мира через выявление и разрешение внутренних противоречий, лежащих в основе развития любых систем и понятий.'),
  ('Майевтика', 'Сократический метод ведения беседы, при котором учитель не сообщает готовых истин, а с помощью наводящих вопросов помогает собеседнику самостоятельно прийти к знанию.'),
  ('Апория', 'В античной философии — трудноразрешимая логическая проблема или кажущееся противоречие между данными опыта и строгим логическим рассуждением (знаменитые апории Зенона).'),
  ('Антиномия', 'Ситуация в логике и философии, при которой два взаимно противоречащих друг другу утверждения имеют одинаково убедительные, строго выведенные доказательства.'),
  ('Дихотомия', 'Последовательное деление целого на две непересекающиеся и взаимоисключающие части, а также противопоставление двух концепций или явлений.'),
  ('Силлогизм', 'Классическое дедуктивное умозаключение в логике Аристотеля, состоящее из двух посылок и логически необходимого вывода из них.'),
  ('Софизм', 'Умозаключение, внешне кажущееся логически правильным, но содержащее скрытую преднамеренную ошибку или подмену понятий для доказательства ложного тезиса.'),
  ('Энтимема', 'Сокращённый силлогизм, в котором одна из посылок или сам вывод явно не проговариваются, а подразумеваются слушателем как очевидные.'),
  ('Тавтология', 'В риторике — неоправданное повторение близких по смыслу слов («масло масляное»); в логике — формула или высказывание, остающееся истинным при любых значениях входящих в него утверждений.'),
  ('Плеоназм', 'Речевой оборот с избыточными по смыслу словами («спуститься вниз», «первый дебют»), который в обычной речи считается ошибкой, но в поэзии служит выразительности.'),
  ('Оксюморон', 'Стилистическая фигура, соединяющая два противоположных по смыслу понятия, которые вместе рождают новый образ («живой труп», «горячий снег», «звонкая тишина»).'),
  ('Литота', 'Художественное преуменьшение или смягчение признака («мальчик с пальчик», «небезызвестный») — приём, противоположный гиперболе.'),
  ('Метонимия', 'Троп, основанный на замене одного слова другим по смежности явлений (например: «весь зал аплодировал» вместо «зрители в зале», или «читать Пушкина» вместо «читать произведения Пушкина»).'),
  ('Синекдоха', 'Разновидность метонимии, при которой часть называется вместо целого или единственное число вместо множественного («все флаги в гости будут к нам»).'),
  ('Реминисценция', 'Неявная, часто полуосознанная отсылка в произведении искусства или речи к более раннему тексту, музыкальному мотиву или культурному образу.'),
  ('Аллюзия', 'Стилистический приём — намёк на общеизвестный исторический факт, миф, библейский сюжет или литературное произведение без прямого их упоминания.'),
  ('Палимпсест', 'Древняя рукопись на пергаменте, с которой смыли или соскоблили прежний текст, чтобы написать новый. В переносном смысле — многослойный культурный или архитектурный объект.'),
  ('Инкунабула', 'Первопечатная книга, изданная в Европе от начала книгопечатания (около 1450 года) до 1 января 1501 года, когда книги ещё внешне имитировали рукописи.'),
  ('Маргиналия', 'Рукописная заметка, комментарий или рисунок на полях книги, сделанные читателем или переписчиком; также небольшие философские заметки «на полях».'),
  ('Гапакс', 'Слово или языковая форма, встретившаяся во всём корпусе текстов данного языка, эпохи или автора ровно один раз (от греч. hapax legomenon).'),
  ('Палиндром', 'Слово, число или целая фраза, одинаково читающиеся слева направо и справа налево (например: «А роза упала на лапу Азора»).'),
  ('Анаграмма', 'Литературный приём перестановки букв одного слова или словосочетания с целью получения нового слова (например, «приказ» — «каприз»).'),
  ('Ономатопея', 'Звукоподражание — образование слов, фонетически воспроизводящих звуки природы, животных или механизмов («жужжать», «тик-так», «шелест»).'),
  ('Аллитерация', 'Повторение одинаковых или однородных согласных звуков в стихе или прозе для придания речи особой музыкальности и выразительности.'),
  ('Ассонанс', 'Повторение ударных или созвучных гласных звуков в строке текста или стихотворении, а также неточная рифма, основанная на совпадении только гласных.'),
  ('Коннотация', 'Сопутствующий эмоциональный, оценочный или культурный оттенок значения слова, дополняющий его прямое словарное определение.'),
  ('Полисемия', 'Многозначность — способность одного и того же слова обладать несколькими исторически связанными между собой значениями («ключ», «корень», «мир»).'),
  ('Эвфемизм', 'Нейтральное или смягчённое слово или выражение, используемое для замены грубых, резких или неуместных по этикету слов.'),
  ('Анахронизм', 'Ошибочное или намеренное перенесение событий, предметов, понятий или языковых оборотов одной исторической эпохи в другую.'),
  ('Синкретизм', 'Первоначальная нерасчленённость различных видов искусства или форм знания (например, единство песни, танца и обряда в древней культуре), а также сочетание разнородных взглядов.'),
  ('Эклектика', 'Соединение в одном произведении, архитектурном стиле или учении элементов разных эпох, направлений и систем взглядов.'),
  ('Эмерджентный', 'Возникающий неожиданно на уровне целостной системы как результат сложного взаимодействия её частей, не сводимый к свойствам отдельных компонентов.'),
  ('Квалиа', 'В философии сознания — субъективные качества чувственного опыта: то, как именно ощущается красный цвет, боль или вкус яблока «изнутри» сознания.'),
  ('Интенциональность', 'Фундаментальное свойство человеческого сознания быть всегда направленным на какой-либо предмет, мысль или образ (нельзя просто «думать ни о чём»).'),
  ('Имманентный', 'Внутренне присущий самому предмету, явлению или системе, вытекающий из его собственной природы, в отличие от привнесённого извне.'),
  ('Трансцендентный', 'Выходящий за пределы возможного чувственного опыта и границ материального мира; в философии Канта — принципиально недоступный эмпирическому познанию.'),
  ('Трансцендентальный', 'В философии Иммануила Канта — относящийся к априорным (доопытным) условиям самого человеческого познания, делающим опыт возможным.'),
  ('Ноумен', 'Понятие философии Канта, обозначающее «вещь в себе» — предмет, мыслимый чистым разумом вне зависимости от того, как он является нашим органам чувств.'),
  ('Симулякр', 'Копия или образ, не имеющий реального оригинала в действительности; знак, подменяющий собой подлинную реальность.'),
  ('Архетип', 'Первообраз, устойчивая универсальная модель восприятия и поведения в коллективном бессознательном (по Карлу Юнгу), отражённая в мифах, сказках и литературе.'),
  ('Парадигма', 'Совокупность фундаментальных научных установок, представлений и образцов решения задач, признанных научным сообществом в определённую эпоху (термин Томаса Куна).'),
  ('Верификация', 'Проверка истинности теоретического положения или научной гипотезы путём сопоставления с опытом, наблюдениями или расчётами.'),
  ('Фальсифицируемость', 'Критерий научности теории, предложенный философом Карлом Поппером: теория научна только тогда, когда принципиально возможно поставить эксперимент, способный её опровергнуть.'),
  ('Редукционизм', 'Методологический подход, стремящийся объяснить сложные явления исключительно через свойства более простых, базовых элементов (например, биологию через химию и физику).'),
  ('Холизм', 'Философская позиция, утверждающая приоритет целого над его частями: целостная система обладает смыслом и законами, которые нельзя понять по частям.'),
  ('Детерминизм', 'Учение о всеобщей причинно-следственной обусловленности всех явлений природы и мира, при которой текущее состояние однозначно определяет последующее.'),
  ('Контингентность', 'Философское понятие случайности в смысле «могло бы быть иначе»: событие или явление существует, но не является логически или онтологически неизбежным.'),
  ('Абдукция', 'Вид логического вывода, при котором от наблюдаемого результата делается предположение о наиболее вероятной объясняющей его причине (основа научных гипотез и диагностики).'),
  ('Дедукция', 'Метод рассуждения от общих положений и законов к частным выводам, гарантирующий истинность заключения при истинности исходных посылок.'),
  ('Индукция', 'Метод познания, ведущий от множества частных наблюдений и фактов к общему правилу или вероятностной закономерности.'),
  ('Эвристика', 'Совокупность приёмов творческого поиска и практических правил, позволяющих быстро находить хорошие (пусть не всегда идеально строгие) решения сложных задач.'),
  ('Метапознание', '«Мышление о мышлении» — способность человека наблюдать, анализировать и осознанно регулировать собственные когнитивные процессы и способы обучения.'),
  ('Рефлексия', 'Обращение сознания на самого себя: осмысление человеком собственных мыслей, чувств, поступков, мотивов и того, как они воспринимаются другими.'),
  ('Интроспекция', 'Метод самонаблюдения, при котором человек внимательно исследует содержание и ход собственных психических переживаний.'),
  ('Когнитивный диссонанс', 'Психологический дискомфорт, возникающий при столкновении в сознании противоречащих друг другу убеждений, знаний или ценностей (концепция Леона Фестингера).'),
  ('Прокрастинация', 'Склонность к постоянному откладыванию важных и срочных дел на потом, приводящая к внутреннему напряжению и потере продуктивности.'),
  ('Конфабуляция', 'Психологический или неврологический феномен ложных воспоминаний, при котором человек искренне воспринимает вымышленные детали памяти как реально пережитые события.'),
  ('Дежавю', 'Психическое состояние, при котором возникает отчётливое ощущение, что происходящая прямо сейчас новая ситуация уже переживалась в прошлом.'),
  ('Жамевю', 'Явление, противоположное дежавю: внезапное ощущение полной новизны и незнакомости привычного места, слова или хорошо знакомого человека.'),
  ('Прескевю', 'Состояние «на кончике языка», когда человек твёрдо знает слово, имя или факт и чувствует, что вот-вот его вспомнит, но не может сразу воспроизвести.'),
  ('Алекситимия', 'Индивидуальная психологическая особенность, выражающаяся в затруднении распознавать, различать и описывать словами собственные эмоции и чувства.'),
  ('Амбивалентность', 'Одновременное переживание человеком двух противоположных чувств или установок к одному объекту (например, притяжения и отторжения).'),
  ('Персеверация', 'Устойчивое, непроизвольное повторение одной и той же мысли, слова, мелодии или действия даже после того, как вызвавший их стимул исчез.'),
  ('Сублимация', 'Психологический защитный механизм и творческий процесс преобразования внутреннего эмоционального напряжения в социально ценную деятельность: искусство, науку или труд.'),
  ('Фрустрация', 'Психическое состояние разочарования и напряжения, возникающее при столкновении с непреодолимым препятствием на пути к важной цели.'),
  ('Импринтинг', 'Запечатление — форма быстрого и прочного запоминания образов и реакций в раннем критическом периоде развития (открыта этологом Конрадом Лоренцем).'),
  ('Ригидность', 'Трудность или неспособность гибко перестраивать мышление, привычки и поведение при изменении внешних условий и обстоятельств.'),
  ('Лабильность', 'Высокая подвижность и быстрая изменчивость процессов — в психологии (быстрая смена эмоций) или в физиологии (скорость протекания нервных импульсов).'),
  ('Гомеостаз', 'Способность открытой системы (в частности живого организма) сохранять постоянство внутренней среды за счёт согласованной саморегуляции.'),
  ('Энтропия', 'В термодинамике и теории информации — мера беспорядка, рассеивания энергии и неопределённости системы, возрастающая в замкнутых системах со временем.'),
  ('Негэнтропия', 'Отрицательная энтропия — мера упорядоченности, организации и структурированности системы, характерная для живых организмов и интеллектуальной деятельности.'),
  ('Бифуркация', 'Разветвление траектории развития динамической системы, при котором малое изменение параметров вызывает резкий качественный переход к новому состоянию.'),
  ('Сингулярность', 'Точка, в которой математическая функция обращается в бесконечность или теряет гладкость; в астрофизике — область сверхвысокой плотности, в теории систем — точка качественного скачка.'),
  ('Суперпозиция', 'Принцип наложения состояний или волн; в квантовой механике — способность системы находиться в комбинации нескольких состояний до момента измерения.'),
  ('Интерференция', 'Взаимное усиление или ослабление волн (световых, звуковых, водных) при их наложении друг на друга в пространстве.'),
  ('Дифракция', 'Огибание волнами препятствий и отклонение от прямолинейного распространения при прохождении через узкие отверстия или вблизи краёв объектов.'),
  ('Прецессия', 'Медленное коническое вращение оси вращающегося тела (например, волчка или земной оси, совершающей полный оборот примерно за 25 772 года).'),
  ('Аберрация', 'Отклонение от нормы или искажение изображения в оптических системах; в астрономии — кажущееся смещение звёзд из-за движения Земли и конечной скорости света.'),
  ('Альбедо', 'Величина, характеризующая отражательную способность поверхности небесного тела, снега, воды или материала (отношение отражённого света к падающему).'),
  ('Апогей', 'Наиболее удалённая от Земли точка орбиты Луны или искусственного спутника; в переносном смысле — высшая точка расцвета или напряжения.'),
  ('Перигелий', 'Ближайшая к Солнцу точка орбиты планеты, кометы или иного небесного тела Солнечной системы.'),
  ('Парсек', 'Внесистемная единица измерения расстояний в астрономии, равная примерно 3,26 светового года (или около 30,86 триллиона километров).'),
  ('Эклиптика', 'Большой круг небесной сферы, по которому происходит видимый годичный путь Солнца среди звёзд, совпадающий с плоскостью орбиты Земли.'),
  ('Зенит', 'Точка небесной сферы, расположенная строго над головой наблюдателя; в переносном смысле — вершина славы, успеха или развития.'),
  ('Надир', 'Точка небесной сферы, противоположная зениту и расположенная прямо под ногами наблюдателя по направлению к центру Земли.'),
  ('Люминесценция', 'Нетепловое свечение вещества, происходящее после поглощения им энергии (например, свечение светлячков или люминофоров без сильного нагрева).'),
  ('Иризация', 'Оптический эффект радужного перелива цветов на поверхности минералов (например, лабрадорита), перламутра, мыльных пузырей или облаков.'),
  ('Фрактал', 'Геометрическая фигура или математическое множество, обладающее свойством самоподобия: отдельные фрагменты повторяют структуру целого в уменьшенном масштабе.'),
  ('Изоморфизм', 'Взаимно однозначное соответствие между элементами двух систем или математических структур, при котором полностью сохраняются отношения между элементами.'),
  ('Синергия', 'Эффект взаимного усиления, при котором совместное действие нескольких факторов превосходит простую сумму их разрозненных результатов.'),
  ('Симбиоз', 'Тесное и длительное сосуществование организмов разных видов, приносящее пользу хотя бы одному из них (в широком смысле — взаимовыгодное сотрудничество).'),
  ('Конвергенция', 'Сближение или независимое формирование сходных признаков у разных систем, биологических видов или культур в сходных условиях среды.'),
  ('Дивергенция', 'Расхождение признаков и свойств у первоначально близких систем, видов или языков в процессе их эволюции и развития.'),
  ('Экстраполяция', 'Метод научного прогнозирования, при котором выявленные на известном участке закономерности распространяются за пределы изученного диапазона.'),
  ('Интерполяция', 'Нахождение промежуточных неизвестных значений величины или функции по имеющемуся набору известных соседних точек.'),
  ('Аппроксимация', 'Научный и математический приём замены сложных объектов или функций более простыми, но достаточно близкими к исходным по своим свойствам.'),
  ('Корреляция', 'Статистическая взаимосвязь между двумя или несколькими величинами, которая сама по себе ещё не означает прямой причинно-следственной связи.'),
  ('Каузальность', 'Причинность — объективная связь между явлениями, при которой одно событие (причина) с необходимостью порождает другое (следствие).'),
  ('Итерация', 'Повторное применение математической операции, алгоритма или творческого шага к результату предыдущего цикла для постепенного приближения к идеалу.'),
  ('Пропедевтика', 'Вводный, подготовительный курс в какую-либо науку или искусство, систематически излагающий базовые понятия перед углублённым изучением.'),
  ('Полимат', 'Учёный или мыслитель-энциклопедист, обладающий глубокими познаниями и выдающимися достижениями сразу в нескольких разных областях науки и культуры (как Леонардо или Ломоносов).'),
  ('Эрудит', 'Человек с обширным кругозором и глубокой начитанностью в различных сферах науки, истории и искусства.'),
  ('Эфемерный', 'Мимолётный, кратковременный, быстро исчезающий (от греч. ephemeros — однодневный).'),
  ('Перманентный', 'Постоянный, непрерывный, длящийся без существенных перерывов на протяжении длительного времени.'),
  ('Априори', 'Знание, предшествующее опыту и выведенное логическим или теоретическим путём независимо от конкретных наблюдений.'),
  ('Апостериори', 'Знание, полученное исключительно на основании практического опыта, экспериментов и наблюдений.'),
  ('Магнум опус', 'От лат. magnum opus («великий труд») — главное, самое значительное и вершиное произведение всей жизни автора, художника или учёного.'),
  ('Статус-кво', 'Сложившееся на определённый момент положение дел, существующее равновесие обстоятельств или правовых отношений.'),
  ('Прерогатива', 'Исключительное право, полномочие или преимущество, принадлежащее определённому лицу, институту или специалисту.'),
  ('Консенсус', 'Общее согласие по спорному вопросу, достигнутое участниками обсуждения без формального голосования и путём учёта позиций всех сторон.'),
  ('Дискурс', 'Связная речь и способ мышления, рассматриваемые в единстве с культурным, историческим и коммуникативным контекстом.'),
  ('Нарратив', 'Повествование, выстроенная последовательность событий и смыслов, через которую человек или культура осмысливает свой опыт.'),
  ('Эксплицитный', 'Выраженный явно, открыто, чётко сформулированный и не требующий догадок.'),
  ('Имплицитный', 'Подразумеваемый, скрытый в подтексте, присутствующий неявно без прямого словесного обозначения.'),
  ('Семиотика', 'Наука о знаках и знаковых системах, исследующая способы передачи и хранения смысла в языке, искусстве, ритуалах и культуре.'),
  ('Этимология', 'Раздел языкознания, изучающий происхождение слов, их первоначальную форму и историческое изменение значений.'),
  ('Палеография', 'Вспомогательная историческая дисциплина, изучающая древние рукописи, эволюцию начертания букв, материалы письма и способы датировки памятников письменности.'),
  ('Эпиграфика', 'Историческая наука, изучающая древние и средневековые надписи на твёрдых материалах — камне, металле, керамике или дереве.'),
  ('Геральдика', 'Историческая дисциплина, изучающая гербы, их символику, историю происхождения и строгие правила составления.'),
  ('Нумизматика', 'Вспомогательная историческая наука, изучающая историю монетной чеканки и денежного обращения по сохранившимся монетам.'),
  ('Сфумато', 'Живописный приём мягкого, дымчатого сглаживания контуров и светотени, создающий ощущение воздушной перспективы (доведён до совершенства Леонардо да Винчи).'),
  ('Кьяроскуро', 'Выразительный контраст света и глубокой тени в живописи и графике, придающий композиции объём и драматизм (мастерски применялся Рембрандтом и Караваджо).'),
  ('Пуантилизм', 'Направление в живописи, при котором картина пишется раздельными мазками-точками чистых красок, оптически смешивающимися непосредственно в глазу зрителя.'),
  ('Филигрань', 'Ювелирная техника создания тончайших кружевных узоров из скрученной металлической проволоки (скань), а также водяной знак на старинной бумаге.'),
  ('Патина', 'Тонкая защитная и декоративная плёнка, образующаяся со временем на поверхности бронзы, меди или латуни и придающая им благородный старинный оттенок.'),
  ('Витраж', 'Произведение декоративного искусства из кусочков цветного стекла, рассчитанное на сквозное освещение и создающее игру цветного света в интерьере.'),
  ('Фреска', 'Техника настенной живописи водяными красками по свежей, ещё влажной известковой штукатурке, благодаря чему роспись становится частью самой стены.'),
  ('Арабеска', 'Сложный ритмичный орнамент из переплетённых геометрических и растительных мотивов; также название поэтической или музыкальной миниатюры.'),
  ('Крещендо', 'Музыкальный термин, обозначающий постепенное нарастание силы звука; в переносном смысле — плавное усиление эмоционального напряжения или событий.'),
  ('Диминуэндо', 'Музыкальный приём постепенного ослабления громкости звучания, создающий эффект затихания или удаления.'),
  ('Полифония', 'Многоголосие — склад музыки, в котором одновременно звучат и развиваются несколько самостоятельных равноправных мелодических линий (вершина — фуги Баха).'),
  ('Контрапункт', 'Одновременное гармоничное сочетание двух или более самостоятельных мелодий; в широком смысле — художественное сопоставление разных смысловых линий.'),
  ('Лейтмотив', 'Устойчивый, многократно повторяющийся музыкальный оборот или ключевая тема в литературном произведении, выражающие главную идею или образ.'),
  ('Меценат', 'Человек, бескорыстно и на постоянной основе поддерживающий развитие науки, искусства, образования и литературы (по имени римлянина Гая Цильния Мецената).'),
  ('Филантропия', 'Бескорыстная благотворительность и забота о благе людей, выражающаяся в поддержке просвещения, медицины, культуры и помощи нуждающимся.'),
  ('Альтруизм', 'Нравственный принцип и модель поведения, основанные на бескорыстной заботе о благополучии других людей даже в ущерб собственной выгоде.'),
  ('Стоицизм', 'Античная философская школа (Зенон, Сенека, Марк Аврелий), учащая сохранять внутреннее достоинство, разумность и стойкость перед превратностями судьбы.'),
  ('Аскетизм', 'Практика добровольного самоограничения в материальных удовольствиях ради духовного сосредоточения, ясности ума и нравственного совершенствования.'),
  ('Скептицизм', 'Философская позиция и метод критического мышления, требующий проверки утверждений доказательствами и ставящий под сомнение поспешные догмы.'),
  ('Рационализм', 'Философское направление, признающее разум решающей основой достоверного познания и критерием истинности представлений о мире.'),
  ('Эмпиризм', 'Учение в теории познания, утверждающее, что единственным надёжным источником всех наших знаний о мире является чувственный опыт и эксперимент.'),
  ('Энциклопедизм', 'Стремление к широкому, системному охвату различных отраслей человеческого знания и соединению научных открытий в единую картину мира.'),
  ('Ноосфера', '«Сфера разума» — концепция, развитая В. И. Вернадским, согласно которой научная мысль и разумная деятельность человека становятся главной преобразующей силой на планете.'),
  ('Бионика', 'Прикладная наука на стыке биологии и инженерии, создающая технические устройства и архитектурные формы по принципам, подсказанным живой природой.'),
  ('Кибернетика', 'Наука об общих закономерностях управления, связи и передачи информации в сложных системах — как в машинах, так и в живых организмах.'),
  ('Криптография', 'Наука о математических методах обеспечения конфиденциальности, целостности и подлинности информации.'),
  ('Мнемотехника', 'Совокупность приёмов и способов, облегчающих запоминание больших объёмов информации путём создания ярких зрительных и смысловых ассоциаций.'),
  ('Солипсизм', 'Крайняя философская позиция, согласно которой единственной несомненной реальностью является собственное индивидуальное сознание субъекта.'),
  ('Панспермия', 'Научная гипотеза о том, что микроскопические зачатки жизни могли быть занесены на Землю из космического пространства с метеоритами или космической пылью.'),
  ('Антропоцен', 'Современная геологическая и экологическая концепция, описывающая эпоху, в которой деятельность человечества заметно влияет на экосистемы и климат Земли.'),
  ('Неизбывность', 'Глубокая, непреходящая со временем сила чувства, впечатления или памяти, от которой невозможно просто освободиться.'),
  ('Благоговение', 'Глубочайшее уважение и почтительное восхищение перед величием природы, искусства, научного гения или нравственного подвига.'),
  ('Лаконизм', 'Краткость, точность и ёмкость изложения мыслей без единого лишнего слова (название восходит к жителям древней Лаконии — спартанцам).'),
  ('Велеречивость', 'Торжественная, многословная и напыщенная манера речи с избытком возвышенных оборотов.'),
  ('Апокриф', 'Древнее религиозное или историко-литературное сочинение, не включённое в официальный канон, но представляющее большой интерес для историков культуры.'),
  ('Сентенция', 'Краткое нравоучительное или философское изречение, выражающее обобщённую жизненную мудрость.'),
  ('Афоризм', 'Оригинальная законченная мысль, высказанная в предельно сжатой, отточенной и легко запоминающейся словесной форме.'),
  ('Панегирик', 'Торжественная похвальная речь или литературное произведение, прославляющее выдающиеся заслуги человека или событие.'),
  ('Элегия', 'Лирическое стихотворение или музыкальное произведение, проникнутое светлой грустью и философским размышлением о быстротечности жизни.'),
  ('Эпиграмма', 'В античности — краткая надпись на камне или памятнике; в Новое время — острое, короткое сатирическое стихотворение.'),
  ('Пролегомены', 'Введение в науку или философию, содержащее предварительные разъяснения, постановку основных вопросов и обзор понятий перед изучением главного труда.'),
  ('Перфекционизм', 'Стремление к безупречности и доведению любого результата до идеала, способное вдохновлять на мастерство или вызывать чрезмерную самокритичность.'),
  ('Версатильность', 'Многосторонность и гибкость ума или таланта, способность одинаково свободно и успешно проявлять себя в самых разных областях.'),
  ('Дилетант', 'Человек, занимающийся наукой или искусством без специальной подготовки, но с живым интересом (изначально в Италии так называли увлечённых любителей музыки и живописи).'),
  ('Альма-матер', 'От лат. alma mater («кормящая мать») — поэтическое название университета, академии или школы, давшей человеку образование и духовное становление.'),
  ('Презумпция', 'Предположение, признаваемое достоверным до тех пор, пока не доказано обратное (один из важнейших принципов логики и права).'),
  ('Калейдоскоп', 'Оптический прибор-трубка с зеркалами и цветными стёклышками, создающий бесконечное множество симметричных узоров; метафора быстрой смены ярких впечатлений.'),
  ('Фата-моргана', 'Редкое и сложное атмосферное явление — многослойный мираж, при котором над горизонтом возникают причудливые искажённые изображения далёких объектов.'),
  ('Ультрамарин', 'Глубокий насыщенно-синий пигмент, в старину получавшийся из редкого минерала лазурита, который привозили в Европу «из-за моря» (лат. ultramarinus).'),
  ('Аквамарин', 'Прозрачный драгоценный камень (разновидность берилла) нежного цвета морской воды (лат. aqua marina).'),
  ('Гобелен', 'Сотканный вручную декоративный настенный ковёр-картина с сюжетной или орнаментальной композицией.'),
  ('Мозаика', 'Изображение или узор, составленный из множества мелких плотно подогнанных кусочков смальты, камня, стекла или керамики.'),
  ('Зарница', 'Мгновенная тихая вспышка на ночном или вечернем горизонте, вызванная отблеском далёкой грозы, когда грома уже не слышно.'),
  ('Метаболизм', 'Обмен веществ — совокупность взаимосвязанных химических процессов в живом организме, обеспечивающих рост, обновление клеток и получение энергии.'),
  ('Диффузия', 'Самопроизвольное взаимное проникновение молекул или атомов одного вещества в другое вследствие их непрерывного теплового движения.'),
  ('Осмос', 'Одностороннее движение молекул растворителя (например, воды) через полупроницаемую мембрану в сторону большей концентрации растворённого вещества.'),
  ('Апофеоз', 'Высшая точка прославления, торжества или завершения какого-либо явления, идеи или художественного замысла.'),
  ('Синонимия', 'Явление языка, при котором разные по звучанию и написанию слова совпадают или очень близки по своему лексическому значению.'),
  ('Омонимия', 'Совпадение по звучанию или написанию разных слов, не связанных между собой по смыслу (например: «лук» — оружие и «лук» — растение).'),
  ('Пароним', 'Слово, близкое другому по звучанию и отчасти по корню, но различающееся по смыслу (например: «адресат» и «адресант», «надеть» и «одеть»).'),
  ('Дискретность', 'Прерывность, разделённость на отдельные чёткие элементы или шаги (в противоположность непрерывности — континууму).'),
  ('Континуум', 'Непрерывная, неразрывная среда или совокупность явлений, плавно переходящих друг в друга без резких границ.'),
  ('Флуктуация', 'Случайное отклонение физической или статистической величины от её среднего значения в системе из множества частиц или элементов.'),
  ('Катализатор', 'Вещество, ускоряющее химическую реакцию и при этом само не расходующееся; в переносном смысле — фактор, ускоряющий перемены.'),
  ('Диссипация', 'Рассеяние энергии упорядоченного движения и её постепенный переход в теплоту или более простые формы.'),
  ('Осцилляция', 'Регулярное колебание системы или величины вокруг устойчивого положения равновесия.'),
  ('Резонанс', 'Резкое возрастание амплитуды колебаний системы при совпадении частоты внешнего воздействия с её собственной частотой; в обществе — живой отклик.'),
  ('Метаморфоза', 'Глубокое и наглядное превращение формы, строения или характера явления — от превращения гусеницы в бабочку до эволюции человеческого характера.'),
  ('Провиденциализм', 'Историософский взгляд, рассматривающий ход истории как осуществление высшего замысла или закономерной предопределённости.'),
  ('Утопия', 'Образ идеального, гармоничного общества будущего, названный по одноимённому сочинению Томаса Мора 1516 года («место, которого нет»).'),
  ('Антиутопия', 'Литературное или философское предостережение, изображающее общество, в котором стремление к искусственному порядку привело к подавлению человеческой природы.'),
  ('Меритократия', 'Принцип организации управления и общества, при котором ответственные позиции занимают наиболее способные, образованные и заслуженные люди.'),
  ('Плюрализм', 'Признание многообразия равноправных научных взглядов, культурных традиций и мнений в рамках закона и конструктивного диалога.'),
  ('Полиглот', 'Человек, свободно владеющий многими языками и способный мыслить в рамках нескольких языковых культур.'),
  ('Каллиграфия', 'Искусство красивого, ритмичного и выразительного письма от руки, ценимое в европейской, арабской и восточноазиатской традициях.'),
  ('Астролябия', 'Старинный угломерный астрономический прибор, позволявший мореплавателям и учёным определять широту, время и высоту небесных светил.'),
  ('Армиллярная сфера', 'Древний астрономический инструмент из подвижных колец, моделирующий небесную сферу и движение светил вокруг Земли.'),
  ('Хронометр', 'Механические часы высочайшей точности, изобретение которых в XVIII веке позволило мореплавателям точно вычислять долготу в океане.'),
  ('Пантеон', 'Знаменитый римский «храм всех богов» с величественным бетонным куполом; в современном языке — условное собрание великих деятелей науки и культуры.'),
  ('Лабиринт', 'Сооружение со сложной сетью запутанных ходов (мифологический лабиринт Дедала на Крите); метафора трудной задачи или запутанного поиска.'),
  ('Рубикон', 'Небольшая река в Италии, переход через которую стал символом бесповоротного, судьбоносного решения («перейти Рубикон»).'),
  ('Нить Ариадны', 'Выражение из древнегреческого мифа о Тесее и Минотавре, обозначающее путеводный принцип или идею, помогающую найти выход из сложнейшей ситуации.'),
  ('Ахиллесова пята', 'Мифологический образ единственного уязвимого места у сильного человека или безупречной на вид системы.'),
  ('Дамоклов меч', 'Античная метафора постоянной скрытой угрозы, нависающей над человеком даже среди внешнего благополучия.'),
  ('Пиррова победа', 'Победа, доставшаяся настолько высокой ценой, что она равносильна поражению (по имени античного полководца Пирра Эпирского).'),
  ('Сизифов труд', 'Бесконечная, изнурительная и безрезультатная работа, названная по мифу о коринфском царе Сизифе.'),
  ('Гордиев узел', 'Предельно запутанное переплетение обстоятельств, требующее смелого, нестандартного решения («разрубить гордиев узел»).'),
  ('Прокрустово ложе', 'Искусственная мерка, под которую насильственно пытаются подогнать живые факты или оригинальные идеи вопреки их природе.'),
  ('Опалесценция', 'Красивое молочно-голубоватое свечение и рассеяние света в мутных средах или благородном опале.'),
  ('Пастораль', 'Жанр литературы, живописи и музыки, воспевающий мирную, гармоничную сельскую жизнь и близость человека к природе.'),
  ('Квинтэссенция', 'Самое главное, суть и сердцевина явления, идеи или произведения; в античной натурфилософии — тончайший пятый элемент мироздания, эфир.'),
  ('Апология', 'Аргументированная защита и обоснование какой-либо идеи, учения или личности (классический пример — «Апология Сократа» Платона).'),
  ('Эмпирей', 'В античной и средневековой космологии — самая высокая, светоносная сфера небес; в поэзии — символ возвышенного, оторванного от быта вдохновения.'),
  ('Талмудизм', 'Буквальное, догматическое следование заученным цитатам без учёта живого смысла и меняющихся фактов реальности.'),
  ('Схоластика', 'Средневековая философско-богословская традиция, стремившаяся соединить логику Аристотеля с вероучением; в разговорной речи — оторванное от практики умствование.'),
  ('Парадокс', 'Утверждение, резко расходящееся со здравым смыслом или привычными ожиданиями, но при внимательном рассмотрении раскрывающее глубокую истину.'),
  ('Симметрия', 'Соразмерность и инвариантность объекта относительно определённых преобразований — фундаментальный принцип гармонии в природе, искусстве и физике.'),
  ('Анамнез', 'В медицине — совокупность сведений об истории болезни и жизни пациента; у Платона — учение о познании как «припоминании» душой вечных идей.'),
  ('Экспозиция', 'Начальная часть литературного или музыкального произведения, знакомящая с героями, местом действия и основными темами.'),
  ('Перипетия', 'Неожиданный, резкий поворот в развитии сюжета драмы или реальной жизненной истории (по Аристотелю — важный элемент композиции).'),
  ('Фабула', 'Фактическая хронологическая последовательность событий в произведении, в отличие от сюжета — того, как эти события выстроены автором.'),
  ('Апперцепция', 'В психологии и философии — зависимость восприятия новых впечатлений от прошлого опыта, знаний и общего склада личности человека.'),
  ('Гештальт', 'Целостный образ или конфигурация восприятия, свойства которой не сводятся к сумме отдельных деталей (термин немецкой психологии начала XX века).'),
  ('Инсайт', 'Внезапное, отчётливое озарение, позволяющее сразу увидеть решение сложной интеллектуальной или творческой задачи без долгого перебора вариантов.'),
  ('Провидение', 'В философии и культуре — высший разумный замысел или удивительное предвидение хода будущих событий.'),
  ('Импровизация', 'Создание музыки, поэзии, речи или сценического действия непосредственно в момент исполнения без предварительной жёсткой записи.'),
  ('Экзегеза', 'Глубокое филологическое и историческое комментирование и разъяснение смысла древних текстов.'),
  ('Сенсуализм', 'Направление в теории познания, считающее ощущения и восприятие первичным фундаментом всей душевной жизни и знания.'),
  ('Деконструкция', 'Метод внимательного чтения текстов и культурных понятий, раскрывающий скрытые в них внутренние противоречия и многослойность смыслов.'),
  ('Контекст', 'Законченное смысловое окружение слова, факта или события, без учёта которого невозможно точно понять его значение.'),
  ('Преамбула', 'Вводная часть важного документа, договора или закона, излагающая цели, принципы и исторические предпосылки его принятия.'),
  ('Лексикография', 'Раздел языкознания, занимающийся теорией и практикой составления словарей — толковых, этимологических, переводных и энциклопедических.'),
  ('Астероид', 'Малое небесное тело Солнечной системы, движущееся по орбите вокруг Солнца и значительно уступающее планетам по размерам.'),
  ('Аксиома', 'Исходное положение какой-либо научной теории, принимаемое в рамках данной системы без доказательства в качестве основы для выведения остальных теорем.'),
  ('Лемма', 'В математике и логике — вспомогательное доказанное утверждение, используемое как ступенька для доказательства более крупной теоремы.'),
  ('Теорема', 'Математическое или логическое утверждение, истинность которого строго доказывается путём рассуждений на основе аксиом и ранее доказанных фактов.'),
  ('Асимптота', 'Прямая линия, к которой график функции или кривая бесконечно близко приближается по мере удаления в бесконечность, так её и не касаясь.'),
  ('Алгоритм', 'Точная конечная последовательность понятных шагов, приводящая к решению поставленной задачи (термин восходит к имени среднеазиатского учёного аль-Хорезми).'),
  ('Космология', 'Раздел астрономии и физики, изучающий строение, происхождение и эволюцию Вселенной как единого целого.'),
  ('Астрофизика', 'Наука, применяющая законы физики и химии для исследования природы звёзд, галактик, туманностей и космических процессов.'),
  ('Экзопланета', 'Планета, обращающаяся вокруг другой звезды за пределами Солнечной системы. На сегодня астрономами открыты тысячи таких миров.'),
  ('Магнитосфера', 'Область пространства вокруг планеты, защищающая её от потоков заряженных частиц солнечного ветра благодаря собственному магнитному полю.'),
  ('Солнцестояние', 'Астрономический момент, когда высота Солнца над горизонтом в полдень достигает наибольшего (летом) или наименьшего (зимой) значения в году.'),
  ('Равноденствие', 'Два дня в году (в марте и сентябре), когда солнечные лучи падают отвесно на экватор, а продолжительность дня и ночи на всей Земле почти равна.'),
  ('Инкубация', 'В психологии творчества — этап бессознательной обработки задачи, когда после долгого обдумывания человек отвлекается, и позже приходит решение.'),
  ('Сублингвальный', 'В медицине и физиологии — способ введения веществ путём помещения их под язык для быстрого попадания в кровоток.'),
  ('Криогеника', 'Отрасль физики и техники, изучающая получение и использование сверхнизких температур (ниже −150 °C) и поведение веществ в таких условиях.'),
  ('Сверхпроводимость', 'Квантовое явление полного исчезновения электрического сопротивления у некоторых материалов при охлаждении ниже критической температуры.'),
  ('Сверхтекучесть', 'Способность квантовой жидкости (например, жидкого гелия вблизи абсолютного нуля) протекать через мельчайшие капилляры без всякого трения и вязкости.'),
  ('Пироэлектричество', 'Возникновение электрических зарядов на поверхности некоторых кристаллов при изменении их температуры.'),
  ('Пьезоэффект', 'Способность ряда кристаллов генерировать электрическое напряжение при механическом сжатии или деформироваться под действием электрического поля.'),
  ('Ломоносов', 'Михаил Васильевич Ломоносов (1711–1765) — великий русский учёный-энциклопедист, физик, химик, астроном, поэт, реформатор русского языка и инициатор основания Московского университета.'),
  ('Менделеев', 'Дмитрий Иванович Менделеев (1834–1907) — великий русский химик и энциклопедист, открывший Периодический закон химических элементов и создавший Периодическую систему.'),
  ('Лобачевский', 'Николай Иванович Лобачевский (1792–1856) — выдающийся русский математик, создатель неевклидовой геометрии, изменившей фундаментальные представления о пространстве.'),
  ('Чебышёв', 'Пафнутий Львович Чебышёв (1821–1894) — знаменитый русский математик и механик, основоположник петербургской математической школы, автор трудов по теории чисел и вероятностей.'),
  ('Ковалевская', 'Софья Васильевна Ковалевская (1850–1891) — выдающийся русский математик и механик, первая в мире женщина — профессор математики и член-корреспондент Петербургской академии наук.'),
  ('Эйлер', 'Леонард Эйлер (1707–1783) — один из величайших математиков и механиков XVIII века, внёсший колоссальный вклад в развитие науки, работая долгие годы в Петербургской академии наук.'),
  ('Колмогоров', 'Андрей Николаевич Колмогоров (1903–1987) — выдающийся советский математик XX века, создатель современной аксиоматики теории вероятностей, теории турбулентности и алгоритмической теории информации.'),
  ('Перельман', 'Григорий Яковлевич Перельман (род. 1966) — выдающийся российский математик, доказавший знаменитую гипотезу Пуанкаре (одну из семи «задач тысячелетия»).'),
  ('Павлов', 'Иван Петрович Павлов (1849–1936) — великий русский физиолог, создатель учения о высшей нервной деятельности, первый русский лауреат Нобелевской премии (1904).'),
  ('Сеченов', 'Иван Михайлович Сеченов (1829–1905) — основоположник русской физиологической школы, автор знаменитого труда «Рефлексы головного мозга».'),
  ('Мечников', 'Илья Ильич Мечников (1845–1916) — выдающийся русский биолог и микробиолог, лауреат Нобелевской премии (1908) за открытие фагоцитоза и разработку основ иммунологии.'),
  ('Пирогов', 'Николай Иванович Пирогов (1810–1881) — великий русский хирург, анатом и педагог, основоположник военно-полевой хирургии и применения эфирного наркоза.'),
  ('Бехтерев', 'Владимир Михайлович Бехтерев (1857–1927) — выдающийся русский невропатолог, психиатр и физиолог, описавший важные структуры мозга и основатель Психоневрологического института.'),
  ('Вернадский', 'Владимир Иванович Вернадский (1863–1945) — выдающийся русский естествоиспытатель и мыслитель, основоположник геохимии, биогеохимии и учений о биосфере и ноосфере.'),
  ('Бутлеров', 'Александр Михайлович Бутлеров (1828–1886) — великий русский химик, создатель теории химического строения органических веществ.'),
  ('Попов', 'Александр Степанович Попов (1859–1906) — выдающийся русский физик и электротехник, изобретатель радиосвязи, продемонстрировавший первый радиоприёмник в 1895 году.'),
  ('Циолковский', 'Константин Эдуардович Циолковский (1857–1935) — русский учёный-самоучка и изобретатель, основоположник теоретической космонавтики, выведший формулу ракетного движения.'),
  ('Королёв', 'Сергей Павлович Королёв (1907–1966) — выдающийся советский конструктор и организатор ракетно-космической отрасли, под чьим руководством был запущен первый спутник и состоялся полёт Гагарина.'),
  ('Гагарин', 'Юрий Алексеевич Гагарин (1934–1968) — советский лётчик-космонавт, Герой Советского Союза, первый человек в мировой истории, совершивший полёт в космическое пространство (12 апреля 1961 года).'),
  ('Леонов', 'Алексей Архипович Леонов (1934–2019) — советский космонавт, дважды Герой Советского Союза, первый человек в истории, вышедший в открытый космос (18 марта 1965 года).'),
  ('Терешкова', 'Валентина Владимировна Терешкова (род. 1937) — первая в мире женщина-космонавт, совершившая одиночный космический полёт на корабле «Восток-6» в июне 1963 года.'),
  ('Курчатов', 'Игорь Васильевич Курчатов (1903–1960) — выдающийся советский физик, академик, научный руководитель советского атомного проекта и мирного использования атомной энергии.'),
  ('Ландау', 'Лев Давидович Ландау (1908–1968) — великий советский физик-теоретик, лауреат Нобелевской премии (1962) за исследования теории конденсированных сред и сверхтекучести гелия.'),
  ('Капица', 'Пётр Леонидович Капица (1894–1984) — выдающийся советский физик, лауреат Нобелевской премии (1978), открывший явление сверхтекучести жидкого гелия.'),
  ('Алфёров', 'Жорес Иванович Алфёров (1930–2019) — выдающийся советский и российский физик, лауреат Нобелевской премии (2000) за разработку полупроводниковых гетероструктур.'),
  ('Тамм', 'Игорь Евгеньевич Тамм (1895–1971) — советский физик-теоретик, лауреат Нобелевской премии (1958) за объяснение эффекта Вавилова — Черенкова.'),
  ('Черенков', 'Павел Алексеевич Черенков (1904–1990) — советский физик-экспериментатор, лауреат Нобелевской премии (1958) за открытие свечения, возникающего при движении заряженных частиц быстрее света в среде.'),
  ('Басов', 'Николай Геннадиевич Басов (1922–2001) — выдающийся советский физик, лауреат Нобелевской премии (1964), один из создателей квантовой электроники и лазеров.'),
  ('Прохоров', 'Александр Михайлович Прохоров (1916–2002) — выдающийся советский физик, лауреат Нобелевской премии (1964) за фундаментальные труды по квантовой электронике и созданию мазеров и лазеров.'),
  ('Семёнов', 'Николай Николаевич Семёнов (1896–1986) — выдающийся советский физикохимик, единственный советский лауреат Нобелевской премии по химии (1956) за теорию цепных реакций.'),
  ('Келдыш', 'Мстислав Всеволодович Келдыш (1911–1978) — выдающийся советский математик и механик, президент Академии наук СССР, один из главных теоретиков советской космической программы.'),
  ('Шухов', 'Владимир Григорьевич Шухов (1853–1939) — гениальный русский инженер, архитектор и изобретатель, создатель гиперболоидных конструкций, включая знаменитую Шуховскую башню в Москве.'),
  ('Туполев', 'Андрей Николаевич Туполев (1888–1972) — выдающийся советский авиаконструктор, создатель десятков типов гражданских и специальных самолётов серии «Ту».'),
  ('Сикорский', 'Игорь Иванович Сикорский (1889–1972) — знаменитый авиаконструктор русского происхождения, создатель первых в мире многомоторных самолётов («Илья Муромец») и серийных вертолётов.'),
  ('Выготский', 'Лев Семёнович Выготский (1896–1934) — выдающийся отечественный психолог, создатель культурно-исторической теории развития психики и понятия «зоны ближайшего развития».'),
  ('Лурия', 'Александр Романович Лурия (1902–1977) — всемирно известный советский психолог, один из основателей нейропсихологии как самостоятельной научной дисциплины.'),
  ('Вавилов', 'Николай Иванович Вавилов (1887–1943) — выдающийся русский и советский учёный-генетик, ботаник и географ, открывший закон гомологических рядов и центры происхождения культурных растений.'),
  ('Тимирязев', 'Климент Аркадьевич Тимирязев (1843–1920) — крупный русский естествоиспытатель, физиолог растений, исследователь фотосинтеза и блестящий популяризатор науки.'),
  ('Кнорозов', 'Юрий Валентинович Кнорозов (1922–1999) — выдающийся советский и российский историк и лингвист, сумевший дешифровать древнюю письменность индейцев майя.'),
  ('Зворыкин', 'Владимир Козьмич Зворыкин (1888–1982) — выдающийся инженер русского происхождения, один из главных изобретателей современного электронного телевидения (создатель иконоскопа).'),
  ('Пушкин', 'Александр Сергеевич Пушкин (1799–1837) — великий русский поэт, драматург и прозаик, заложивший основы современного русского литературного языка.'),
  ('Лермонтов', 'Михаил Юрьевич Лермонтов (1814–1841) — великий русский поэт, прозаик и драматург, автор романа «Герой нашего времени» и поэм «Мцыри» и «Демон».'),
  ('Гоголь', 'Николай Васильевич Гоголь (1809–1852) — великий русский прозаик и драматург, автор «Мёртвых душ», «Ревизора» и «Вечеров на хуторе близ Диканьки».'),
  ('Достоевский', 'Фёдор Михайлович Достоевский (1821–1881) — великий русский писатель и мыслитель, автор романов «Преступление и наказание», «Идиот», «Братья Карамазовы», оказавший огромное влияние на мировую литературу и философию.'),
  ('Толстой', 'Лев Николаевич Толстой (1828–1910) — великий русский писатель и мыслитель, автор эпопеи «Война и мир» и романа «Анна Каренина», один из крупнейших мастеров психологического реализма.'),
  ('Чехов', 'Антон Павлович Чехов (1860–1904) — великий русский писатель, драматург и врач, мастер краткого рассказа и создатель новой драмы («Вишнёвый сад», «Три сестры», «Чайка»).'),
  ('Тургенев', 'Иван Сергеевич Тургенев (1818–1883) — классик русской литературы XIX века, автор романов «Отцы и дети», «Дворянское гнездо» и цикла «Записки охотника».'),
  ('Булгаков', 'Михаил Афанасьевич Булгаков (1891–1940) — выдающийся русский писатель, драматург и врач, автор романа «Мастер и Маргарита», «Собачьего сердца» и «Белой гвардии».'),
  ('Бунин', 'Иван Алексеевич Бунин (1870–1953) — русский писатель и поэт, первый русский лауреат Нобелевской премии по литературе (1933), мастер тонкой лирической прозы.'),
  ('Куприн', 'Александр Иванович Куприн (1870–1938) — известный русский писатель-реалист, автор повестей «Гранатовый браслет», «Олеся» и «Поединок».'),
  ('Грибоедов', 'Александр Сергеевич Грибоедов (1795–1829) — русский драматург, поэт, дипломат и композитор, автор знаменитой комедии в стихах «Горе от ума».'),
  ('Крылов', 'Иван Андреевич Крылов (1769–1844) — великий русский баснописец, публицист и библиотекарь, чьи строки вошли в живую народную речь в качестве пословиц.'),
  ('Карамзин', 'Николай Михайлович Карамзин (1766–1826) — выдающийся русский историк и писатель, реформатор русского языка, автор многотомной «Истории государства Российского».'),
  ('Тютчев', 'Фёдор Иванович Тютчев (1803–1873) — великий русский поэт-философ и дипломат, мастер лирики природы и глубоких размышлений о судьбе и мироздании.'),
  ('Фет', 'Афанасий Афанасьевич Фет (1820–1892) — выдающийся русский поэт-лирик и переводчик, знаменитый музыкальностью стиха и тонкой передачей мгновенных переживаний.'),
  ('Некрасов', 'Николай Алексеевич Некрасов (1821–1878) — великий русский поэт, прозаик и издатель журнала «Современник», автор поэмы «Кому на Руси жить хорошо».'),
  ('Блок', 'Александр Александрович Блок (1880–1921) — один из крупнейших русских поэтов Серебряного века, классик русского символизма, автор цикла «Стихи о Прекрасной Даме» и поэмы «Двенадцать».'),
  ('Есенин', 'Сергей Александрович Есенин (1895–1925) — великий русский поэт, мастер проникновенной крестьянской и любовной лирики, воспевший красоту русской природы.'),
  ('Маяковский', 'Владимир Владимирович Маяковский (1893–1930) — знаменитый русский и советский поэт-новатор, драматург и художник, один из ярчайших представителей поэзии XX века.'),
  ('Ахматова', 'Анна Андреевна Ахматова (1889–1966) — выдающаяся русская поэтесса Серебряного века и XX столетия, мастер акмеизма и глубокой трагической лирики.'),
  ('Пастернак', 'Борис Леонидович Пастернак (1890–1960) — русский поэт, прозаик и переводчик (в том числе трагедий Шекспира и «Фауста» Гёте), лауреат Нобелевской премии по литературе (1958).'),
  ('Цветаева', 'Марина Ивановна Цветаева (1892–1941) — одна из самых самобытных русских поэтесс XX века, известная страстной интонацией, ритмическим новаторством и прозой о поэтах.'),
  ('Шолохов', 'Михаил Александрович Шолохов (1905–1984) — великий русский советский писатель, лауреат Нобелевской премии по литературе (1965), автор романа-эпопеи «Тихий Дон».'),
  ('Даль', 'Владимир Иванович Даль (1801–1872) — русский учёный, врач, писатель и лексикограф, составитель знаменитого «Толкового словаря живого великорусского языка».'),
  ('Ожегов', 'Сергей Иванович Ожегов (1900–1964) — выдающийся советский лингвист и лексикограф, автор самого популярного однотомного «Словаря русского языка».'),
  ('Лихачёв', 'Дмитрий Сергеевич Лихачёв (1906–1999) — выдающийся отечественный филолог, культуролог, академик, исследователь древнерусской литературы и автор «Писем о добром и прекрасном».'),
  ('Лотман', 'Юрий Михайлович Лотман (1922–1993) — выдающийся советский литературовед, культуролог и семиотик, создатель тартуско-московской семиотической школы и исследователь культуры пушкинской эпохи.'),
  ('Бахтин', 'Михаил Михайлович Бахтин (1895–1975) — всемирно известный русский философ, культуролог и теоретик литературы, разработавший концепции диалогизма, полифонии и хронотопа.'),
  ('Лосев', 'Алексей Фёдорович Лосев (1893–1988) — выдающийся русский философ и филолог, автор фундаментальной многотомной «Истории античной эстетики».'),
  ('Пропп', 'Владимир Яковлевич Пропп (1895–1970) — знаменитый советский филолог-фольклорист, автор классического труда «Морфология волшебной сказки», лёгшего в основу современной теории сюжета.'),
  ('Чайковский', 'Пётр Ильич Чайковский (1840–1893) — великий русский композитор, дирижёр и педагог, автор балетов «Лебединое озеро», «Щелкунчик», опер «Евгений Онегин» и «Пиковая дама».'),
  ('Рахманинов', 'Сергей Васильевич Рахманинов (1873–1943) — великий русский композитор, виртуозный пианист и дирижёр, синтезировавший традиции русского романтизма и XX века.'),
  ('Мусоргский', 'Модест Петрович Мусоргский (1839–1881) — великий русский композитор-новатор, участник «Могучей кучки», автор оперы «Борис Годунов» и цикла «Картинки с выставки».'),
  ('Римский-Корсаков', 'Николай Андреевич Римский-Корсаков (1844–1908) — великий русский композитор, дирижёр и мастер оркестровки, автор сюиты «Шехеразада» и опер «Садко» и «Снегурочка».'),
  ('Бородин', 'Александр Порфирьевич Бородин (1833–1887) — выдающийся русский композитор и крупный учёный-химик, автор эпической оперы «Князь Игорь».'),
  ('Глинка', 'Михаил Иванович Глинка (1804–1857) — основоположник русской классической музыкальной школы, автор опер «Жизнь за царя» и «Руслан и Людмила».'),
  ('Прокофьев', 'Сергей Сергеевич Прокофьев (1891–1953) — один из крупнейших композиторов XX века, автор балета «Ромео и Джульетта», симфонической сказки «Петя и волк» и музыки к фильмам Эйзенштейна.'),
  ('Шостакович', 'Дмитрий Дмитриевич Шостакович (1906–1975) — великий советский композитор и пианист, автор пятнадцати симфоний, включая знаменитую Седьмую («Ленинградскую») симфонию.'),
  ('Стравинский', 'Игорь Фёдорович Стравинский (1882–1971) — выдающийся русский композитор-новатор XX века, автор знаменитых балетов «Жар-птица», «Петрушка» и «Весна священная».'),
  ('Скрябин', 'Александр Николаевич Скрябин (1872–1915) — русский композитор и пианист-символист, одним из первых в истории соединивший симфоническую музыку со световыми образами («цветомузыка»).'),
  ('Репин', 'Илья Ефимович Репин (1844–1930) — великий русский художник-реалист, мастер исторической и портретной живописи («Бурлаки на Волге», «Запорожцы», «Не ждали»).'),
  ('Айвазовский', 'Иван Константинович Айвазовский (1817–1900) — великий русский художник-маринист, создавший свыше шести тысяч произведений, посвящённых морю и морской истории («Девятый вал»).'),
  ('Шишкин', 'Иван Иванович Шишкин (1832–1898) — выдающийся русский живописец-пейзажист и гравёр, академик, мастер изображения русского леса («Утро в сосновом лесу», «Рожь»).'),
  ('Левитан', 'Исаак Ильич Левитан (1860–1900) — великий русский художник, создатель «пейзажа настроения», передававший тончайшие состояния русской природы («Над вечным покоем», «Золотая осень»).'),
  ('Врубель', 'Михаил Александрович Врубель (1856–1910) — выдающийся русский художник-символист и скульптор, известный кристаллическим мазком и философской выразительностью образов («Демон», «Царевна-Лебедь»).'),
  ('Серов', 'Валентин Александрович Серов (1865–1911) — великий русский живописец и портретист, мастер психологического портрета («Девочка с персиками», «Похищение Европы»).'),
  ('Суриков', 'Василий Иванович Суриков (1848–1916) — выдающийся русский мастер масштабных исторических полотен («Боярыня Морозова», «Переход Суворова через Альпы»).'),
  ('Васнецов', 'Виктор Михайлович Васнецов (1848–1926) — известный русский художник-передвижник, основоположник неорусского стиля в живописи и архитектуре («Богатыри», «Алёнушка»).'),
  ('Куинджи', 'Архип Иванович Куинджи (1842–1910) — великий русский художник-пейзажист и педагог, прославившийся поразительными световыми эффектами в живописи («Лунная ночь на Днепре»).'),
  ('Брюллов', 'Карл Павлович Брюллов (1799–1852) — знаменитый русский живописец и монументалист, блестящий представитель классицизма и романтизма («Последний день Помпеи», «Всадница»).'),
  ('Рублёв', 'Андрей Рублёв (ок. 1360–1428) — великий русский иконописец и мастер монументальной живописи московской школы, создатель знаменитой «Троицы».'),
  ('Станиславский', 'Константин Сергеевич Станиславский (1863–1938) — великий русский режиссёр, актёр и педагог, сооснователь МХТ и создатель всемирно признанной системы актёрского мастерства.'),
  ('Тарковский', 'Андрей Арсеньевич Тарковский (1932–1986) — выдающийся советский кинорежиссёр и теоретик искусства, автор философских фильмов «Андрей Рублёв», «Солярис», «Зеркало» и «Сталкер».'),
  ('Эйзенштейн', 'Сергей Михайлович Эйзенштейн (1898–1948) — выдающийся советский кинорежиссёр и теоретик кино, один из создателей современного языка киномонтажа («Броненосец „Потёмкин“», «Александр Невский»).'),
  ('Плисецкая', 'Майя Михайловна Плисецкая (1925–2015) — величайшая балерина XX века, прима Большого театра и балетмейстер, воплотившая высочайшее мастерство русского классического танца.'),
  ('Архимед', 'Архимед Сиракузский (ок. 287–212 до н. э.) — величайший древнегреческий математик, физик и инженер, открывший закон выталкивающей силы и заложивший основы механики и интегральных вычислений.'),
  ('Пифагор', 'Пифагор Самосский (ок. 570–490 до н. э.) — древнегреческий философ и математик, основатель пифагорейской школы, учивший, что в основе гармонии мира и музыки лежат числовые соотношения.'),
  ('Евклид', 'Евклид Александрийский (ок. 325–265 до н. э.) — древнегреческий математик, автор фундаментального труда «Начала», по которому геометрию изучали более двух тысяч лет.'),
  ('Сократ', 'Сократ (ок. 469–399 до н. э.) — древнегреческий философ, повернувший философию к исследованию человека, этики и самопознания («Я знаю, что ничего не знаю»).'),
  ('Платон', 'Платон (ок. 427–347 до н. э.) — великий древнегреческий философ, ученик Сократа, основатель Афинской Академии и создатель философского учения о мире вечных идей.'),
  ('Аристотель', 'Аристотель (384–322 до н. э.) — великий древнегреческий философ и учёный-энциклопедист, создатель формальной логики и автор трудов по физике, этике, поэтике и биологии.'),
  ('Гиппократ', 'Гиппократ Косский (ок. 460–370 до н. э.) — знаменитый древнегреческий врач, «отец медицины», отделивший врачевание от суеверий и заложивший основы медицинской этики.'),
  ('Коперник', 'Николай Коперник (1473–1543) — польский и европейский астроном эпохи Возрождения, создатель гелиоцентрической системы мира, положивший начало первой научной революции.'),
  ('Галилей', 'Галилео Галилей (1564–1642) — великий итальянский физик, астроном и механик, одним из первых направивший телескоп в небо и утвердивший экспериментальный метод в науке.'),
  ('Кеплер', 'Иоганн Кеплер (1571–1630) — выдающийся немецкий математик и астроном, открывший три точных закона движения планет вокруг Солнца.'),
  ('Ньютон', 'Исаак Ньютон (1643–1727) — великий английский физик, математик и астроном, сформулировавший законы классической механики, всемирного тяготения и создавший дифференциальное исчисление.'),
  ('Лейбниц', 'Готфрид Вильгельм Лейбниц (1646–1716) — немецкий философ, математик и энциклопедист, независимо от Ньютона создавший математический анализ и описавший двоичную систему счисления.'),
  ('Декарт', 'Рене Декарт (1596–1650) — выдающийся французский философ и математик, создатель аналитической геометрии (декартовой системы координат) и автор тезиса «Мыслю, следовательно, существую».'),
  ('Паскаль', 'Блез Паскаль (1623–1662) — выдающийся французский математик, физик и философ, один из основателей гидростатики, теории вероятностей и создатель одной из первых счётных машин.'),
  ('Спиноза', 'Бенедикт Спиноза (1632–1677) — нидерландский философ-рационалист, построивший строгую этическую систему и учение о единой субстанции природы.'),
  ('Кант', 'Иммануил Кант (1724–1804) — великий немецкий философ, родоначальник немецкой классической философии, автор «Критики чистого разума» и формулировки категорического императива.'),
  ('Гегель', 'Георг Вильгельм Фридрих Гегель (1770–1831) — крупнейший немецкий философ, создатель всеобъемлющей системы диалектики и учения о развитии мирового духа в истории.'),
  ('Шопенгауэр', 'Артур Шопенгауэр (1788–1860) — немецкий философ, автор знаменитого сочинения «Мир как воля и представление», оказавший глубокое влияние на философию и литературу XIX–XX веков.'),
  ('Гаусс', 'Карл Фридрих Гаусс (1777–1855) — великий немецкий математик, астроном и физик, прозванный «королём математиков» за фундаментальные открытия в алгебре, геометрии и теории чисел.'),
  ('Фарадей', 'Майкл Фарадей (1791–1867) — великий английский физик-экспериментатор и химик, открывший явление электромагнитной индукции, на котором основана вся современная энергетика.'),
  ('Максвелл', 'Джеймс Клерк Максвелл (1831–1879) — великий шотландский физик, создавший классическую электродинамику и показавший, что свет представляет собой электромагнитную волну.'),
  ('Дарвин', 'Чарльз Роберт Дарвин (1809–1882) — великий английский натуралист и путешественник, создавший научную теорию эволюции путём естественного отбора.'),
  ('Мендель', 'Грегор Иоганн Мендель (1822–1884) — австрийский естествоиспытатель, открывший базовые законы наследственности и заложивший фундамент современной генетики.'),
  ('Пастер', 'Луи Пастер (1822–1895) — великий французский микробиолог и химик, доказавший микробную природу брожения и болезней и создавший методы вакцинации и пастеризации.'),
  ('Тесла', 'Никола Тесла (1856–1943) — выдающийся инженер и изобретатель сербского происхождения, внёсший решающий вклад в развитие систем переменного тока, электродвигателей и радиотехники.'),
  ('Кюри', 'Мария Склодовская-Кюри (1867–1934) и Пьер Кюри — великие физики и химики, первооткрыватели радиоактивности, полония и радия; Мария Кюри — первый дважды лауреат Нобелевской премии.'),
  ('Эйнштейн', 'Альберт Эйнштейн (1879–1955) — величайший физик-теоретик XX века, создатель специальной и общей теории относительности, лауреат Нобелевской премии за объяснение фотоэффекта.'),
  ('Планк', 'Макс Планк (1858–1947) — великий немецкий физик-теоретик, основоположник квантовой физики, лауреат Нобелевской премии (1918), введший понятие кванта действия.'),
  ('Бор', 'Нильс Бор (1885–1962) — выдающийся датский физик-теоретик, лауреат Нобелевской премии (1922), один из главных создателей квантовой механики и модели строения атома.'),
  ('Гейзенберг', 'Вернер Гейзенберг (1901–1976) — немецкий физик-теоретик, один из создателей квантовой механики, сформулировавший фундаментальный принцип неопределённости.'),
  ('Шрёдингер', 'Эрвин Шрёдингер (1887–1961) — австрийский физик-теоретик, лауреат Нобелевской премии (1933), автор основного уравнения волновой механики и знаменитого мысленного эксперимента.'),
  ('Фейнман', 'Ричард Филлипс Фейнман (1918–1988) — выдающийся американский физик-теоретик, лауреат Нобелевской премии (1965) за квантовую электродинамику и блестящий популяризатор науки.'),
  ('Хокинг', 'Стивен Уильям Хокинг (1942–2018) — выдающийся британский физик-теоретик и космолог, автор теории излучения чёрных дыр и знаменитой книги «Краткая история времени».'),
  ('Тьюринг', 'Алан Матисон Тьюринг (1912–1954) — великий британский математик и логик, заложивший теоретические основы информатики, концепции алгоритмических вычислений и искусственного интеллекта.'),
  ('Лавлейс', 'Ада Лавлейс (1815–1852) — английский математик, составившая подробное описание алгоритма для аналитической машины Чарльза Бэббиджа, благодаря чему считается первым программистом в истории.'),
  ('Флеминг', 'Александр Флеминг (1881–1955) — шотландский бактериолог, лауреат Нобелевской премии (1945), открывший пенициллин и положивший начало эре антибиотиков.'),
  ('Магеллан', 'Фернан Магеллан (ок. 1480–1521) — португальский и испанский мореплаватель, возглавивший экспедицию, которая совершила первое в истории кругосветное плавание.'),
  ('Колумб', 'Христофор Колумб (1451–1506) — знаменитый мореплаватель эпохи Великих географических открытий, чья экспедиция 1492 года открыла Новый Свет для европейцев.'),
  ('Да Винчи', 'Леонардо да Винчи (1452–1519) — величайший универсальный гений эпохи Возрождения: живописец («Мона Лиза», «Тайная вечеря»), скульптор, архитектор, анатом и инженер-изобретатель.'),
  ('Микеланджело', 'Микеланджело Буонарроти (1475–1564) — великий итальянский скульптор, живописец и архитектор эпохи Возрождения, создатель «Давида» и росписи Сикстинской капеллы.'),
  ('Рафаэль', 'Рафаэль Санти (1483–1520) — великий итальянский живописец и архитектор Высокого Возрождения, прославившийся гармоничными образами («Сикстинская мадонна», «Афинская школа»).'),
  ('Рембрандт', 'Рембрандт Харменс ван Рейн (1606–1669) — великий голландский живописец и гравёр, непревзойдённый мастер светотени и глубокого психологического портрета («Ночной дозор», «Возвращение блудного сына»).'),
  ('Веласкес', 'Диего Веласкес (1599–1660) — величайший испанский художник золотого века, придворный живописец Филиппа IV и автор шедевра «Менины».'),
  ('Моне', 'Клод Моне (1840–1926) — выдающийся французский живописец, один из основателей импрессионизма, чья картина «Впечатление. Восход солнца» дала название всему течению.'),
  ('Ван Гог', 'Винсент Ван Гог (1853–1890) — великий нидерландский художник-постимпрессионист, чья выразительная палитра и динамичный мазок оказали огромное влияние на живопись XX века («Звёздная ночь»).'),
  ('Сезанн', 'Поль Сезанн (1839–1906) — великий французский художник-постимпрессионист, стремившийся передать глубинную геометрическую структуру природы и проложивший путь живописи XX века.'),
  ('Бах', 'Иоганн Себастьян Бах (1685–1750) — величайший немецкий композитор и органист эпохи барокко, вершина полифонической музыки («Хорошо темперированный клавир», «Токката и фуга ре минор»).'),
  ('Моцарт', 'Вольфганг Амадей Моцарт (1756–1791) — великий австрийский композитор-классик, обладатель феноменального музыкального дара, создавший свыше шестисот бессмертных сочинений.'),
  ('Бетховен', 'Людвиг ван Бетховен (1770–1827) — великий немецкий композитор и пианист, связующее звено между классицизмом и романтизмом, автор Девятой симфонии и «Лунной сонаты».'),
  ('Вивальди', 'Антонио Вивальди (1678–1741) — выдающийся итальянский композитор и скрипач-виртуоз эпохи барокко, создатель знаменитого цикла концертов «Времена года».'),
  ('Шопен', 'Фридерик Шопен (1810–1849) — великий польский композитор и пианист эпохи романтизма, почти всё творчество которого посвящено раскрытию выразительных возможностей фортепиано.'),
  ('Лист', 'Ференц Лист (1811–1886) — великий венгерский композитор и феноменальный пианист-виртуоз XIX века, реформатор концертного исполнительства и создатель жанра симфонической поэмы.'),
  ('Паганини', 'Никколо Паганини (1782–1840) — легендарный итальянский скрипач-виртуоз и композитор, расширивший технические возможности игры на скрипке («24 каприса»).'),
  ('Шекспир', 'Уильям Шекспир (1564–1616) — великий английский драматург и поэт эпохи Возрождения, автор трагедий «Гамлет», «Ромео и Джульетта», «Король Лир» и 154 сонетов.'),
  ('Данте', 'Данте Алигьери (1265–1321) — великий итальянский поэт и мыслитель, один из создателей итальянского литературного языка, автор грандиозной поэмы «Божественная комедия».'),
  ('Сервантес', 'Мигель де Сервантес Сааведра (1547–1616) — великий испанский писатель, автор романа «Хитроумный идальго Дон Кихот Ламанчский», ставшего основой европейского романа.'),
  ('Гёте', 'Иоганн Вольфганг фон Гёте (1749–1832) — великий немецкий поэт, философ и естествоиспытатель, автор философской трагедии «Фауст» и романа «Страдания юного Вертера».'),
  ('Гюго', 'Виктор Гюго (1802–1885) — великий французский писатель, поэт и драматург, глава французского романтизма, автор романов «Собор Парижской Богоматери» и «Отверженные».'),
  ('Бальзак', 'Оноре де Бальзак (1799–1850) — великий французский писатель, классик мирового реализма, автор грандиозной эпопеи «Человеческая комедия».'),
  ('Диккенс', 'Чарльз Диккенс (1812–1870) — величайший английский романист XIX века, автор «Приключений Оливера Твиста», «Дэвида Копперфилда» и «Больших надежд».'),
  ('Верн', 'Жюль Верн (1828–1905) — знаменитый французский писатель, один из основоположников научной фантастики («Двадцать тысяч льё под водой», «Таинственный остров»).'),
  ('Борхес', 'Хорхе Луис Борхес (1899–1986) — выдающийся аргентинский прозаик и поэт XX века, мастер интеллектуальных притч о лабиринтах, бесконечных библиотеках, времени и памяти.'),
  ('Маркес', 'Габриэль Гарсиа Маркес (1927–2014) — выдающийся колумбийский писатель, лауреат Нобелевской премии по литературе (1982), мастер «магического реализма» («Сто лет одиночества»).'),
  ('Кафка', 'Франц Кафка (1883–1924) — один из самых влиятельных писателей XX века, автор повестей и романов «Превращение», «Процесс» и «Замок».'),
  ('Гомер', 'Гомер (ок. VIII в. до н. э.) — легендарный древнегреческий поэт-сказитель, которому традиция приписывает создание древнейших памятников европейской литературы — «Илиады» и «Одиссеи».'),
  ('Сенека', 'Луций Анней Сенека (ок. 4 до н. э. — 65 н. э.) — древнеримский философ-стоик, поэт и государственный деятель, автор знаменитых «Нравственных писем к Луцилию».'),
  ('Аврелий', 'Марк Аврелий (121–180 н. э.) — римский император и выдающийся философ-стоик, оставивший глубокие дневниковые размышления о долге и самообладании («Наедине с собой»).'),
  ('Эзоп', 'Эзоп (ок. VI в. до н. э.) — полулегендарный древнегреческий баснописец, ставший родоначальником жанра короткой поучительной басни и понятия «эзопов язык».'),
  ('Геродот', 'Геродот Галикарнасский (ок. 484–425 до н. э.) — древнегреческий учёный, названный Цицероном «отцом истории» за первый систематический труд «История».'),
  ('Плутарх', 'Плутарх (ок. 45–127 н. э.) — древнегреческий философ и историк, прославившийся знаменитыми «Сравнительными жизнеописаниями» великих деятелей Греции и Рима.'),
  ('Цицерон', 'Марк Туллий Цицерон (106–43 до н. э.) — великий древнеримский оратор, философ и писатель, чьи речи и трактаты стали образцом классической латинской прозы.'),
  ('Вергилий', 'Публий Вергилий Марон (70–19 до н. э.) — величайший поэт Древнего Рима, автор эпической поэмы «Энеида» и буколической поэзии.'),
  ('Конфуций', 'Конфуций (551–479 до н. э.) — великий древнекитайский мыслитель и педагог, чьё этико-философское учение о почитании старших, обучении и самосовершенствовании определило культуру Восточной Азии.'),
  ('Авиценна', 'Ибн Сина, или Авиценна (980–1037) — выдающийся среднеазиатский учёный-энциклопедист, врач и философ, автор знаменитого медицинского труда «Канон врачебной науки».'),
  ('Омар Хайям', 'Омар Хайям (1048–1131) — персидский математик, астроном (создатель точнейшего солнечного календаря), философ и знаменитый поэт, мастер философских четверостиший-рубаи.'),
  ('Гутенберг', 'Иоганн Гутенберг (ок. 1400–1468) — немецкий изобретатель, создавший в Европе в середине XV века способ книгопечатания подвижными металлическими литерами.'),
  ('Ватт', 'Джеймс Ватт (Уатт, 1736–1819) — шотландский инженер-изобретатель, усовершенствовавший паровую машину и ускоривший промышленную революцию; его именем названа единица мощности — ватт.'),
  ('Вольта', 'Алессандро Вольта (1745–1827) — итальянский физик и химик, изобретатель первого химического источника электрического тока (вольтова столба); его именем названа единица напряжения — вольт.'),
  ('Ампер', 'Андре-Мари Ампер (1775–1836) — французский физик и математик, один из основоположников электродинамики; его именем названа единица силы электрического тока — ампер.'),
  ('Герц', 'Генрих Рудольф Герц (1857–1894) — немецкий физик, впервые экспериментально подтвердивший существование электромагнитных волн, предсказанных Максвеллом; его именем названа единица частоты.'),
  ('Рентген', 'Вильгельм Конрад Рентген (1845–1923) — немецкий физик, открывший X-лучи (рентгеновское излучение) и ставший самым первым лауреатом Нобелевской премии по физике (1901).'),
  ('Лавуазье', 'Антуан Лоран Лавуазье (1743–1794) — великий французский естествоиспытатель, один из основателей современной химии, объяснивший роль кислорода в горении и сформулировавший закон сохранения массы.'),
  ('Линней', 'Карл Линней (1707–1778) — шведский натуралист и врач, создатель единой научной системы классификации растительного и животного мира (бинарной номенклатуры).'),
  ('Гумбольдт', 'Александр фон Гумбольдт (1769–1859) — великий немецкий географ, натуралист и путешественник, заложивший основы географии растений, климатологии и комплексного землеведения.'),
  ('Макинтош', 'Чарльз Макинтош (1766–1843) — шотландский химик и изобретатель, создавший водонепроницаемую прорезиненную ткань, давшую название знаменитому плащу-макинтошу.'),
  ('Нобель', 'Альфред Бернхард Нобель (1833–1896) — шведский химик, инженер и предприниматель, получивший свыше 350 патентов и завещавший своё состояние на учреждение Нобелевской премии.'),
  ('Эдисон', 'Томас Алва Эдисон (1847–1931) — американский изобретатель и предприниматель, создатель фонографа, усовершенствовавший лампу накаливания и киноаппаратуру.'),
  ('Белл', 'Александр Грейам Белл (1847–1922) — шотландский и американский учёный и изобретатель, получивший первый патент на телефон и посвятивший много лет помощи людям с нарушениями слуха.'),
  ('Резерфорд', 'Эрнест Резерфорд (1871–1937) — выдающийся британский физик новозеландского происхождения, «отец ядерной физики», открывший атомное ядро и искусственное превращение элементов.'),
  ('Хаббл', 'Эдвин Пауэлл Хаббл (1889–1953) — выдающийся американский астроном, доказавший существование других галактик за пределами Млечного Пути и открывший расширение Вселенной.'),
  ('Саган', 'Карл Эдвард Саган (1934–1996) — американский астроном, астрофизик и выдающийся популяризатор науки, автор знаменитой книги и документального цикла «Космос».'),
  ('Шеннон', 'Клод Элвуд Шеннон (1916–2001) — выдающийся американский математик и инженер, основоположник математической теории информации и теории цифровых схем.'),
  ('Винер', 'Норберт Винер (1894–1964) — американский математик и философ, основоположник кибернетики и теории автоматического управления и обратной связи.'),
  ('Нэш', 'Джон Форбс Нэш (1928–2015) — выдающийся американский математик, лауреат Нобелевской премии по экономике (1994), автор фундаментального понятия равновесия в теории игр.'),
  ('Фон Нейман', 'Джон фон Нейман (1903–1957) — венгро-американский математик-универсал, создатель архитектуры современных компьютеров, теории игр и квантовой логики.'),
  ('Рамануджан', 'Сриниваса Рамануджан (1887–1920) — легендарный индийский математик-самоучка, поразивший учёный мир тысячами глубоких формул в теории чисел, бесконечных рядах и непрерывных дробях.'),
  ('Пуанкаре', 'Анри Пуанкаре (1854–1912) — великий французский математик, физик и философ науки, один из создателей топологии, теории хаоса и предшественник теории относительности.'),
  ('Гильберт', 'Давид Гильберт (1862–1943) — один из самых влиятельных математиков конца XIX — начала XX века, сформулировавший знаменитый список из 23 математических проблем.'),
  ('Гёдель', 'Курт Гёдель (1906–1978) — выдающийся австро-американский логик и математик, доказавший знаменитые теоремы о неполноте формальных математических систем.'),
  ('Ферма', 'Пьер де Ферма (1601–1665) — выдающийся французский математик-любитель и юрист, один из создателей теории чисел, прославившийся Великой теоремой Ферма.'),
  ('Фибоначчи', 'Леонардо Пизанский, известный как Фибоначчи (ок. 1170–1250) — средневековый итальянский математик, познакомивший Европу с арабскими цифрами и описавший знаменитую числовую последовательность.'),
  ('Боттичелли', 'Сандро Боттичелли (1445–1510) — великий итальянский живописец эпохи Раннего Возрождения, автор знаменитых полотен «Рождение Венеры» и «Весна».'),
  ('Караваджо', 'Микеланджело Меризи да Караваджо (1571–1610) — великий итальянский живописец, реформатор европейской живописи XVII века, мастер драматической светотени и реализма.'),
  ('Вермеер', 'Ян Вермеер Делфтский (1632–1675) — великий нидерландский живописец, мастер утончённого камерного жанра и поэтического дневного света («Девушка с жемчужной серёжкой»).'),
  ('Дега', 'Эдгар Дега (1834–1917) — выдающийся французский живописец, график и скульптор, известный динамичными композициями, темой балета и мастерским владением пастелью.'),
  ('Ренуар', 'Пьер Огюст Ренуар (1841–1919) — великий французский художник-импрессионист, воспевший свет, радость жизни, музыку и живую гармонию цвета.'),
  ('Гойя', 'Франсиско Хосе де Гойя (1746–1828) — великий испанский живописец и гравёр эпохи романтизма, создавший проницательные портреты и знаменитую серию офортов «Капричос».'),
  ('Гауди', 'Антонио Гауди (1852–1926) — гениальный каталонский архитектор, создатель уникальных бионических сооружений Барселоны, включая храм Саграда Фамилия и парк Гуэль.'),
  ('Шуберт', 'Франц Шуберт (1797–1828) — великий австрийский композитор, один из основоположников романтизма в музыке, автор более шестисот песен, симфоний и камерных шедевров.'),
  ('Верди', 'Джузеппе Верди (1813–1901) — великий итальянский композитор, реформатор оперного искусства, автор опер «Травиата», «Аида», «Риголетто» и «Отелло».'),
  ('Пуччини', 'Джакомо Пуччини (1858–1924) — выдающийся итальянский оперный композитор, автор всемирно любимых опер «Богема», «Тоска», «Мадам Баттерфляй» и «Турандот».'),
  ('Россини', 'Джоаккино Россини (1792–1868) — знаменитый итальянский композитор, мастер искромётной оперной мелодии, автор «Севильского цирюльника» и «Вильгельма Телля».'),
  ('Григ', 'Эдвард Григ (1843–1907) — великий норвежский композитор эпохи романтизма, воспевший северную природу и фольклор, автор знаменитой сюиты «Пер Гюнт».'),
  ('Дебюсси', 'Клод Дебюсси (1862–1918) — выдающийся французский композитор, основоположник музыкального импрессионизма, создатель тончайших звуковых красок и образов («Лунный свет»).'),
  ('Равель', 'Морис Равель (1875–1937) — выдающийся французский композитор XX века, непревзойдённый мастер оркестровки и ритма, автор знаменитого «Болеро».'),
  ('Гендель', 'Георг Фридрих Гендель (1685–1759) — великий композитор эпохи барокко, мастер монументальных ораторий («Мессия»), опер и инструментальных сюит.'),
  ('Суворов', 'Александр Васильевич Суворов (1730–1800) — великий русский полководец, генералиссимус, не проигравший ни одного сражения, автор знаменитой книги «Наука побеждать».'),
  ('Кутузов', 'Михаил Илларионович Кутузов (1745–1813) — выдающийся русский полководец и дипломат, генерал-фельдмаршал, главнокомандующий русской армией в Отечественной войне 1812 года.'),
  ('Ушаков', 'Фёдор Фёдорович Ушаков (1745–1817) — выдающийся русский флотоводец, адмирал, создатель новой тактики морского боя, не потерявший в сражениях ни одного корабля.'),
  ('Беллинсгаузен', 'Фаддей Фаддеевич Беллинсгаузен (1778–1852) — знаменитый русский мореплаватель и адмирал, один из первооткрывателей Антарктиды (совместно с М. П. Лазаревым в 1820 году).'),
  ('Миклухо-Маклай', 'Николай Николаевич Миклухо-Маклай (1846–1888) — выдающийся русский этнограф, антрополог и путешественник, изучавший народы Новой Гвинеи и Океании и отстаивавший равенство всех людей.'),
  ('Пржевальский', 'Николай Михайлович Пржевальский (1839–1888) — выдающийся русский путешественник, географ и натуралист, исследовавший огромные пространства Центральной Азии.'),
  ('Державин', 'Гавриил Романович Державин (1743–1816) — великий русский поэт эпохи Просвещения и государственный деятель, предтеча пушкинской поэзии, автор оды «Бог» и «Фелица».'),
  ('Жуковский', 'Василий Андреевич Жуковский (1783–1852) — выдающийся русский поэт, один из основоположников русского романтизма и блестящий переводчик «Одиссеи» Гомера.'),
  ('Гончаров', 'Иван Александрович Гончаров (1812–1891) — классик русской литературы XIX века, автор романов «Обломов», «Обыкновенная история» и путевых очерков «Фрегат „Паллада“».'),
  ('Островский', 'Александр Николаевич Островский (1823–1886) — великий русский драматург, создавший национальный репертуар русского театра («Гроза», «Бесприданница», «Снегурочка»).'),
  ('Лесков', 'Николай Семёнович Лесков (1831–1895) — самобытный русский писатель, виртуоз народного сказа и редкого слова, автор «Левши», «Очарованного странника» и «Соборян».'),
  ('Салтыков-Щедрин', 'Михаил Евграфович Салтыков-Щедрин (1826–1889) — великий русский писатель-сатирик и публицист, автор «Истории одного города», «Господ Головлёвых» и острых философских сказок.'),
  ('Паустовский', 'Константин Георгиевич Паустовский (1892–1968) — выдающийся русский советский писатель, мастер поэтической прозы о природе, творчестве и внутреннем мире человека («Золотая роза», «Мещёрская сторона»).'),
  ('Пришвин', 'Михаил Михайлович Пришвин (1873–1954) — русский и советский писатель-мыслитель, создатель тонких философско-лирических миниатюр о природе («Кладовая солнца», «Женьшень»).'),
  ('Бажов', 'Павел Петрович Бажов (1879–1950) — русский советский писатель и фольклорист, автор знаменитого уральского цикла сказов «Малахитовая шкатулка».'),
  ('Твардовский', 'Александр Трифонович Твардовский (1910–1971) — выдающийся русский советский поэт, прозаик и редактор, автор народной поэмы «Василий Тёркин».'),
  ('Шаляпин', 'Фёдор Иванович Шаляпин (1873–1938) — величайший русский оперный и камерный певец (высокий бас), соединивший уникальный голос с гениальным драматическим талантом.'),
  ('Уланова', 'Галина Сергеевна Уланова (1910–1998) — легендарная русская советская балерина, ставшая мировым символом одухотворённой пластики и драматической глубины русского балета.'),
  ('Немирович-Данченко', 'Владимир Иванович Немирович-Данченко (1858–1943) — выдающийся русский театральный режиссёр, драматург и педагог, вместе со Станиславским основавший Московский Художественный театр.'),
  ('Брунеллески', 'Филиппо Брунеллески (1377–1446) — великий итальянский архитектор и инженер, один из основоположников архитектуры Возрождения и теории линейной перспективы.'),
  ('Палладио', 'Андреа Палладио (1508–1580) — великий итальянский архитектор Позднего Возрождения, чьи трактаты и ордерная гармония определили облик классической архитектуры Европы и России.'),
  ('Баженов', 'Василий Иванович Баженов (1737–1799) — выдающийся русский архитектор и теоретик зодчества, один из основоположников русского классицизма (Дом Пашкова, ансамбль Царицыно).'),
  ('Казаков', 'Матвей Фёдорович Казаков (1738–1812) — великий русский архитектор, сформировавший облик классической Москвы (здание Сената в Кремле, Дом Благородного собрания, Голицынская больница).'),
  ('Воронихин', 'Андрей Никифорович Воронихин (1759–1814) — выдающийся русский архитектор эпохи ампира, создатель величественного Казанского собора и Горного института в Санкт-Петербурге.'),
  ('Захаров', 'Андреян Дмитриевич Захаров (1761–1811) — выдающийся русский зодчий стиля ампир, автор одного из главных архитектурных символов Санкт-Петербурга — здания Главного Адмиралтейства.'),
  ('Росси', 'Карл Иванович Росси (1775–1849) — выдающийся архитектор итальянского происхождения, создавший грандиозные градостроительные ансамбли Санкт-Петербурга (Дворцовая площадь, Михайловский дворец).'),
  ('Шехтель', 'Фёдор Осипович Шехтель (1859–1926) — выдающийся русский архитектор и художник, крупнейший мастер русского модерна (особняк Рябушинского, Ярославский вокзал, МХТ).'),
  ('Склифосовский', 'Николай Васильевич Склифосовский (1836–1904) — выдающийся русский хирург, один из пионеров антисептики и асептики в отечественной медицине, основатель клинического городка на Девичьем поле.'),
  ('Боткин', 'Сергей Петрович Боткин (1832–1889) — великий русский врач-терапевт и учёный, основоположник научной клинической медицины в России и концепции целостности организма.'),
  ('Филатов', 'Владимир Петрович Филатов (1875–1956) — выдающийся советский офтальмолог и хирург, совершивший переворот в пересадке роговицы и пластической хирургии.'),
  ('Амосов', 'Николай Михайлович Амосов (1913–2002) — выдающийся советский кардиохирург, учёный-биокибернетик и писатель, разработчик новых методов хирургии сердца и систем здорового долголетия.'),
  ('Илизаров', 'Гавриил Абрамович Илизаров (1921–1992) — выдающийся советский хирург-ортопед, изобретатель знаменитого аппарата внешней фиксации для сращивания и восстановления костей.'),
  ('Калашников', 'Михаил Тимофеевич Калашников (1919–2013) — выдающийся советский и российский конструктор-оружейник, дважды Герой Социалистического Труда и Герой Российской Федерации.'),
  ('Глушко', 'Валентин Петрович Глушко (1908–1989) — выдающийся советский конструктор, один из пионеров ракетно-космической техники, создатель мощных жидкостных ракетных двигателей.'),
  ('Кошкин', 'Михаил Ильич Кошкин (1898–1940) — выдающийся советский инженер-конструктор, создатель и первый главный конструктор легендарного среднего танка Т-34.'),
  ('Фридман', 'Александр Александрович Фридман (1888–1925) — выдающийся русский и советский математик и геофизик, теоретически предсказавший нестационарность (расширение) Вселенной из уравнений Эйнштейна.'),
  ('Боголюбов', 'Николай Николаевич Боголюбов (1909–1992) — выдающийся советский математик и физик-теоретик, внёсший фундаментальный вклад в квантовую теорию поля, статистическую физику и нелинейную механику.'),
  ('Яблочков', 'Павел Николаевич Яблочков (1847–1894) — талантливый русский электротехник и изобретатель, создавший дуговую электрическую лампу («свеча Яблочкова»), осветившую улицы Европы и России.'),
  ('Лодыгин', 'Александр Николаевич Лодыгин (1847–1923) — выдающийся русский электротехник, один из первых изобретателей электрической лампы накаливания и систем с вольфрамовой нитью.'),
  ('Можайский', 'Александр Фёдорович Можайский (1825–1890) — русский морской офицер и изобретатель, пионер отечественной авиации, разработавший один из первых в мире проектов самолёта в натуральную величину.'),
  ('Ильюшин', 'Сергей Владимирович Ильюшин (1894–1977) — выдающийся советский авиаконструктор, трижды Герой Социалистического Труда, создатель легендарного штурмовика Ил-2 и пассажирских лайнеров семейства «Ил».'),
  ('Чаплыгин', 'Сергей Алексеевич Чаплыгин (1869–1942) — выдающийся русский и советский математик и механик, сооснователь ЦАГИ, один из создателей современной гидро- и газовой динамики.'),
  ('Сухой', 'Павел Осипович Сухой (1895–1975) — выдающийся советский авиаконструктор, один из основоположников отечественной реактивной и сверхзвуковой авиации (конструкторское бюро «Су»).'),
  ('Макаров', 'Степан Осипович Макаров (1848–1904) — выдающийся русский флотоводец, океанограф и кораблестроитель, инициатор создания первого в мире арктического ледокола «Ермак».'),
  ('Крузенштерн', 'Иван Фёдорович Крузенштерн (1770–1846) — выдающийся русский мореплаватель и адмирал, возглавивший первое русское кругосветное плавание (1803–1806) и составивший Атлас Южного моря.'),
  ('Дежнёв', 'Семён Иванович Дежнёв (ок. 1605–1673) — знаменитый русский землепроходец и мореход, впервые обогнувший крайнюю северо-восточную оконечность Азии и открывший пролив между Азией и Америкой.'),
  ('Беринг', 'Витус Ионассен Беринг (1681–1741) — выдающийся мореплаватель и офицер русского флота, руководитель Первой и Второй Камчатских экспедиций, открывших берега Аляски и Алеутские острова.'),
  ('Никитин', 'Афанасий Никитин (? — ок. 1475) — тверской купец и путешественник XV века, совершивший беспримерное путешествие в Индию и описавший его в знаменитом памятнике «Хождение за три моря».'),
  ('Остроградский', 'Михаил Васильевич Остроградский (1801–1862) — выдающийся русский математик и механик, академик, автор знаменитой формулы Остроградского — Гаусса в векторном анализе.'),
  ('Анохин', 'Пётр Кузьмич Анохин (1898–1974) — выдающийся советский физиолог, академик, создатель теории функциональных систем, объясняющей целенаправленную работу мозга и организма.'),
  ('Розенталь', 'Дитмар Эльяшевич Розенталь (1900–1994) — выдающийся советский и российский лингвист, автор классических справочников по правописанию и стилистике русского языка.'),
  ('Виноградов', 'Виктор Владимирович Виноградов (1895–1969) — выдающийся советский лингвист и литературовед, академик, создатель учения о русском литературном языке и языке художественной литературы.'),
  ('Саврасов', 'Алексей Кондратьевич Саврасов (1830–1897) — великий русский художник-пейзажист, один из основателей Товарищества передвижников, автор знаменитой картины «Грачи прилетели».'),
  ('Поленов', 'Василий Дмитриевич Поленов (1844–1927) — выдающийся русский художник-пейзажист, мастер пленэра, педагог и просветитель («Московский дворик», «Золотая осень»).'),
  ('Кипренский', 'Орест Адамович Кипренский (1782–1836) — великий русский живописец-романтик и портретист, автор знаменитого прижизненного портрета А. С. Пушкина.'),
  ('Шиллер', 'Фридрих Шиллер (1759–1805) — великий немецкий поэт, философ и драматург, автор драм «Разбойники», «Коварство и любовь» и знаменитой «Оды к радости».'),
  ('Байрон', 'Джордж Гордон Байрон (1788–1824) — великий английский поэт-романтик, автор поэмы «Паломничество Чайльд-Гарольда» и романа в стихах «Дон Жуан».'),
  ('Овидий', 'Публий Овидий Назон (43 до н. э. — ок. 18 н. э.) — выдающийся древнеримский поэт золотого века римской литературы, автор поэмы «Метаморфозы».'),
  ('Флобер', 'Гюстав Флобер (1821–1880) — выдающийся французский прозаик-реалист, стилист мирового уровня, автор романа «Госпожа Бовари».'),
  ('Мопассан', 'Ги де Мопассан (1850–1893) — знаменитый французский писатель, блестящий мастер новеллы и психологического романа («Милый друг», «Пышка»).'),
  ('Дюрер', 'Альбрехт Дюрер (1471–1528) — великий немецкий живописец, гравёр и теоретик искусства эпохи Северного Возрождения.'),
  ('Брейгель', 'Питер Брейгель Старший (ок. 1525–1569) — великий нидерландский живописец и график, прославившийся философскими и живыми народными сценами («Охотники на снегу»).'),
  ('Тициан', 'Тициан Вечеллио (ок. 1488–1576) — великий итальянский живописец, крупнейший мастер венецианской школы эпохи Возрождения, прославившийся богатством колорита.'),
  ('Роден', 'Огюст Роден (1840–1917) — великий французский скульптор, один из основоположников современной пластики, автор знаменитых скульптур «Мыслитель» и «Граждане Кале».'),
  ('Брамс', 'Иоганнес Брамс (1833–1897) — великий немецкий композитор и пианист эпохи романтизма, мастер симфонической и камерной музыки («Венгерские танцы»).'),
  ('Шуман', 'Роберт Шуман (1810–1856) — выдающийся немецкий композитор-романтик и музыкальный критик, автор циклов «Карнавал», «Детские сцены» и вокальной лирики.'),
  ('Гайдн', 'Йозеф Гайдн (1732–1809) — великий австрийский композитор, представитель венской классической школы, прозванный «отцом симфонии и струнного квартета».'),
  ('Мендельсон', 'Феликс Мендельсон-Бартольди (1809–1847) — выдающийся немецкий композитор, дирижёр и пианист эпохи романтизма, возродивший интерес Европы к музыке И. С. Баха.'),
  ('Берлиоз', 'Гектор Берлиоз (1803–1869) — великий французский композитор и дирижёр эпохи романтизма, автор «Фантастической симфонии» и классического трактата об оркестровке.')
